import type {SpokenClip} from './dialogue-voice';
// Generated from exact actor + full displayed text. Narrator and inner voice remain silent.
export const SPOKEN_CLIPS = [
  {
    "speaker": "cheng",
    "text": "好，钥匙先放你那里。想清楚了再告诉我。",
    "src": "/audio/dialogue/cheng.554730f7b660.991ff2cb75c0.mp3",
    "essential": true
  },
  {
    "speaker": "cheng",
    "text": "店铺的租约还有三年。书架、桌子和剩下的书，都可以留下。",
    "src": "/audio/dialogue/cheng.580f60ca660b.cd9f340ac832.mp3",
    "essential": true
  },
  {
    "speaker": "cheng",
    "text": "不管怎么选，后窗都得垫条毛巾。下雨的时候，它总关不严。",
    "src": "/audio/dialogue/cheng.5b3c51676100.55503e9a7b91.mp3",
    "essential": true
  },
  {
    "speaker": "cheng",
    "text": "接手需要押金和整理费。你也可以先帮我照看，不急着出这笔钱。",
    "src": "/audio/dialogue/cheng.7d4af7879de8.7c1c0e69701b.mp3",
    "essential": true
  },
  {
    "speaker": "cao",
    "text": "那就按现有范围用。这段租期先照这个安排，余下的地方仍要避雨。",
    "src": "/audio/dialogue/cao.1147fd8a2e86.80f95d292d78.mp3"
  },
  {
    "speaker": "cao",
    "text": "外面的瓦熬过几场雨，里面这根木梁，这次得处理。",
    "src": "/audio/dialogue/cao.1c8154d11145.c07ae531c14d.mp3"
  },
  {
    "speaker": "cao",
    "text": "季末把付款和完工核对好，再按修好的屋面安排下一季。",
    "src": "/audio/dialogue/cao.1e491e757a7a.73c8aee62fbe.mp3"
  },
  {
    "speaker": "cao",
    "text": "不是修不动，就看你还想用多久。",
    "src": "/audio/dialogue/cao.2b5cbe844a80.589364085ddd.mp3"
  },
  {
    "speaker": "cao",
    "text": "那就按说好的来。要留着的东西，先盖好，别落灰。",
    "src": "/audio/dialogue/cao.3be877487958.5280a00e34b6.mp3"
  },
  {
    "speaker": "cao",
    "text": "两天后过来。备用的先拿去用。",
    "src": "/audio/dialogue/cao.54642e0fcb56.72f2a7b1a9ff.mp3"
  },
  {
    "speaker": "cao",
    "text": "先核项目和付款人。答应过的工程，改动也要在单上写清楚。",
    "src": "/audio/dialogue/cao.a206f1efd739.bb614c2151c0.mp3"
  },
  {
    "speaker": "cao",
    "text": "这一回把剩下的屋面接好了，窗边的书可以搬回去。",
    "src": "/audio/dialogue/cao.b5aca8b85f1d.55f3b92a2df1.mp3"
  },
  {
    "speaker": "cao",
    "text": "商量好就叫我。单上写什么，我就照着什么备材料。",
    "src": "/audio/dialogue/cao.d3243ef1396c.73aa67b90552.mp3"
  },
  {
    "speaker": "cao",
    "text": "先看好施工单，哪些要揭开，哪些留下，今天都得说清。",
    "src": "/audio/dialogue/cao.d4f281b31bed.923154e18366.mp3"
  },
  {
    "speaker": "cao",
    "text": "换新的省事。修这台，要等两天。",
    "src": "/audio/dialogue/cao.d79739e14868.2c671df69a38.mp3"
  },
  {
    "speaker": "cao",
    "text": "照原方案做，或者把范围缩小，都能谈。开工前把改项确认好。",
    "src": "/audio/dialogue/cao.dad1ef4a3a8d.00cfa1b178ba.mp3"
  },
  {
    "speaker": "cao",
    "text": "这次九千。以后补完还有返场费，窗边先留出搬书的位置。",
    "src": "/audio/dialogue/cao.e898a5e9db96.dbc2435f3e83.mp3"
  },
  {
    "speaker": "cao",
    "text": "这张是余下清单。工程一万五，返场两千，总共一万七。",
    "src": "/audio/dialogue/cao.ea31f2fd4cbf.481c1d4fa5f7.mp3"
  },
  {
    "speaker": "cao",
    "text": "先不做也行。收好原单，后面哪一处动过，就照着哪一处验。",
    "src": "/audio/dialogue/cao.ed6026952757.8e236f4de372.mp3"
  },
  {
    "speaker": "cao",
    "text": "回去先试一晚，有问题拿来。",
    "src": "/audio/dialogue/cao.f87f3da114f4.a429d3847bfc.mp3"
  },
  {
    "speaker": "cheng",
    "text": "谁付电费，谁最后检查门窗，临时不能来怎么办，都先说好。",
    "src": "/audio/dialogue/cheng.01626cf8f640.23165aedc91a.mp3"
  },
  {
    "speaker": "cheng",
    "text": "不用给我看账本。我今天只是来坐坐。",
    "src": "/audio/dialogue/cheng.06c1827678b8.6be06288199d.mp3"
  },
  {
    "speaker": "cheng",
    "text": "这次总算烧圆了。你别只拿来装钥匙，盛汤也试一试。",
    "src": "/audio/dialogue/cheng.0a8e03fd033e.66a92d7f878a.mp3"
  },
  {
    "speaker": "cheng",
    "text": "到时候一起收拾。哪些书要留，慢慢理，总能理清楚。",
    "src": "/audio/dialogue/cheng.1b5a45943112.988aa48de7c2.mp3"
  },
  {
    "speaker": "cheng",
    "text": "头一回烧窑，出来的比想的少一半。歪的也还盛得住东西。",
    "src": "/audio/dialogue/cheng.1d5247d25e73.e924eeb062c2.mp3"
  },
  {
    "speaker": "cheng",
    "text": "我在窗边坐了一下午。你们先忙，今天我不赶车。",
    "src": "/audio/dialogue/cheng.2b5fa7a0f02f.51ea6be155b6.mp3"
  },
  {
    "speaker": "cheng",
    "text": "大家能决定怎么开门，也一起决定怎么关门。",
    "src": "/audio/dialogue/cheng.332309bd92b5.5047b81061d3.mp3"
  },
  {
    "speaker": "cheng",
    "text": "这几年，过得怎么样？慢慢说，我们又不赶最后一班车。",
    "src": "/audio/dialogue/cheng.363396c072d5.815f9700d965.mp3"
  },
  {
    "speaker": "cheng",
    "text": "这次我不替大家排事情。你们自己商量。",
    "src": "/audio/dialogue/cheng.5516b496d0de.6a93635fba4b.mp3"
  },
  {
    "speaker": "cheng",
    "text": "你喜欢就做。不喜欢，也别只是怕让我失望。",
    "src": "/audio/dialogue/cheng.58a23d3f87bf.2242e5531a1b.mp3"
  },
  {
    "speaker": "cheng",
    "text": "拿这个再试一炉，出来什么样都拍给你看，歪的也不藏。",
    "src": "/audio/dialogue/cheng.6da6ae82fb6a.4bd27b9a3057.mp3"
  },
  {
    "speaker": "cheng",
    "text": "先端稳，烫着呢。阿棠，把那张空椅子也拉过来。",
    "src": "/audio/dialogue/cheng.8087ecd6e52e.d2fd50e4ae85.mp3"
  },
  {
    "speaker": "cheng",
    "text": "愿意继续，就把责任和保证金日期签下来。不愿意，我们也能商量交接。",
    "src": "/audio/dialogue/cheng.84e765264604.50e0e0d474ad.mp3"
  },
  {
    "speaker": "cheng",
    "text": "你喜欢就接着做。不喜欢，也别为了我，把自己一直耗着。",
    "src": "/audio/dialogue/cheng.88414edd9e2c.3820114aa5c0.mp3"
  },
  {
    "speaker": "cheng",
    "text": "窗边那排书怕晒，记得……你看，我说着说着，又啰嗦了。",
    "src": "/audio/dialogue/cheng.926ae9014cb7.3eb90fb7ed3f.mp3"
  },
  {
    "speaker": "cheng",
    "text": "这几年过得怎么样？别只报一个总数，从你想讲的那件事说起。",
    "src": "/audio/dialogue/cheng.9e89baea8b56.54849bff00c6.mp3"
  },
  {
    "speaker": "cheng",
    "text": "那就少烧几个，先把温度试出来。没必要一回都送进去。",
    "src": "/audio/dialogue/cheng.9ff1ebe494c1.0eb9d09741e9.mp3"
  },
  {
    "speaker": "cheng",
    "text": "收到了就好，别急着回。",
    "src": "/audio/dialogue/cheng.a746be49bbb5.06951b21d201.mp3"
  },
  {
    "speaker": "cheng",
    "text": "关门时间也写上。其他的，我就不添了。",
    "src": "/audio/dialogue/cheng.a898e930801f.68ceed41a473.mp3"
  },
  {
    "speaker": "cheng",
    "text": "进货单在柜台下面，运费也写着，拿给她看看吧。",
    "src": "/audio/dialogue/cheng.a905bcf9add6.9bffeae83409.mp3"
  },
  {
    "speaker": "cheng",
    "text": "边界先说清楚，也让帮忙的人好开口。",
    "src": "/audio/dialogue/cheng.a97f236935c1.70c706820378.mp3"
  },
  {
    "speaker": "cheng",
    "text": "钥匙还在吧？这只套着不硌手，我看着大小正好。",
    "src": "/audio/dialogue/cheng.aa69a13a563f.413173fc9945.mp3"
  },
  {
    "speaker": "cheng",
    "text": "再练练，还是换种釉呢？材料买了不少，总觉得该接着做。",
    "src": "/audio/dialogue/cheng.ba37a4409914.801cefd1ce23.mp3"
  },
  {
    "speaker": "cheng",
    "text": "租约还有三年，书架、桌子和剩下的书，都可以留下来。",
    "src": "/audio/dialogue/cheng.bed62517fce6.ec7edb335fef.mp3"
  },
  {
    "speaker": "cheng",
    "text": "不着急答复。后窗关不严，下雨的时候，记得垫条毛巾。",
    "src": "/audio/dialogue/cheng.d21c6d8b2cff.e506b07588d2.mp3"
  },
  {
    "speaker": "cheng",
    "text": "南方的冬天也冷。我把烧坏的杯子拿去种蒜了。",
    "src": "/audio/dialogue/cheng.da755be555d8.574e401b4e66.mp3"
  },
  {
    "speaker": "cheng",
    "text": "还在就好。颜色你选一个，我再拿近些拍给你看。",
    "src": "/audio/dialogue/cheng.de3e08353aef.7c66686306a1.mp3"
  },
  {
    "speaker": "cheng",
    "text": "这只口歪了，装钥匙倒合适。另一只你试试看，能不能盛汤。",
    "src": "/audio/dialogue/cheng.fce7658681d9.c2caba714278.mp3"
  },
  {
    "speaker": "cheng",
    "text": "这一箱不挣钱，留给附近学校。旁边那几箱别混进来。",
    "src": "/audio/dialogue/cheng.ff977c1ed01e.301066661ce2.mp3"
  },
  {
    "speaker": "gu",
    "text": "这次格式对了。回执留着，后面办手续还得用到。",
    "src": "/audio/dialogue/gu.09c5bc6e7b60.30afd797b290.mp3"
  },
  {
    "speaker": "gu",
    "text": "展览开幕前得拿到成书。接的话，连续三个晚上都得留下。",
    "src": "/audio/dialogue/gu.17c59f0245f2.331ea96136a2.mp3"
  },
  {
    "speaker": "gu",
    "text": "这里少了一个字。电子版经过我们手，纸样已经签过了。",
    "src": "/audio/dialogue/gu.21786c188014.a7859aa694a9.mp3"
  },
  {
    "speaker": "gu",
    "text": "那再版的时候，我们得早点问。",
    "src": "/audio/dialogue/gu.325435de93d5.74f9a84bc524.mp3"
  },
  {
    "speaker": "gu",
    "text": "这三次索引都是我核的。最后排版，名字又没了。",
    "src": "/audio/dialogue/gu.35556e4c616e.f514f07088d9.mp3"
  },
  {
    "speaker": "gu",
    "text": "新人托我带的。味道可能一般，你先喝点热的。",
    "src": "/audio/dialogue/gu.4180bc62a0cc.72d71bf64ec7.mp3"
  },
  {
    "speaker": "gu",
    "text": "新人说下一版再改。现在返工，奖金那边就来不及报了。",
    "src": "/audio/dialogue/gu.57062fe9afbe.cf8b2666660d.mp3"
  },
  {
    "speaker": "gu",
    "text": "他已经接上了，谢啦。你也趁热吃，别又放凉。",
    "src": "/audio/dialogue/gu.7ded2c5753c5.6cf75b3797b6.mp3"
  },
  {
    "speaker": "gu",
    "text": "奖金和验收费的日期不同。你先核过，我去找空的晾纸架。",
    "src": "/audio/dialogue/gu.8c434bfb1e6a.0934175218d8.mp3"
  },
  {
    "speaker": "gu",
    "text": "自愿报名，得自己腾一天。补贴的日期，要看通知下面。",
    "src": "/audio/dialogue/gu.a25bed66fba6.640e30f32f5a.mp3"
  },
  {
    "speaker": "gu",
    "text": "这一版都写全了。你看，名字在这里。",
    "src": "/audio/dialogue/gu.a93e2e720a6b.1094dc30ef22.mp3"
  },
  {
    "speaker": "gu",
    "text": "现在领要少一成，原日期的数也在这儿，签以前看清楚。",
    "src": "/audio/dialogue/gu.c00a7b227a84.31403a65d65f.mp3"
  },
  {
    "speaker": "gu",
    "text": "电子版经过我们手，纸样那边已经签了。",
    "src": "/audio/dialogue/gu.c0fb7d5c1198.01596300371e.mp3"
  },
  {
    "speaker": "gu",
    "text": "那就从这一页重新核。我去借一支灯。",
    "src": "/audio/dialogue/gu.c6a61708b943.aad87b550cdb.mp3"
  },
  {
    "speaker": "gu",
    "text": "我来接着做。你早点回，今天这条街还没到开灯的时候。",
    "src": "/audio/dialogue/gu.c8253f94196f.0d595a1c2346.mp3"
  },
  {
    "speaker": "gu",
    "text": "这次领过，原来的日期就不再发这一笔了，单子收好。",
    "src": "/audio/dialogue/gu.e7183e9bff80.3f592d0f0ea2.mp3"
  },
  {
    "speaker": "gu",
    "text": "版本号我记下了。后面若要改，得先找到今天交的这一份。",
    "src": "/audio/dialogue/gu.f2c9c3bcd9ed.fb7e5adad3f3.mp3"
  },
  {
    "speaker": "gu",
    "text": "这儿得再转一次。我给你演示，你把步骤记下来。",
    "src": "/audio/dialogue/gu.fe2335ab29c1.ab7e28697033.mp3"
  },
  {
    "speaker": "gu",
    "text": "家里就能做，不过晚饭以后得留出时间，你先看一季？",
    "src": "/audio/dialogue/gu.ff2c491ab6e9.8a3151cbe6dd.mp3"
  },
  {
    "speaker": "he",
    "text": "就这个吧。回去你叫车，我今天只管这张桌子。",
    "src": "/audio/dialogue/he.03e6a8c19334.df6d5f96fdee.mp3"
  },
  {
    "speaker": "he",
    "text": "每次都说有空就来，那我要把哪天留给你？",
    "src": "/audio/dialogue/he.08fa949fcceb.7d775ba911ce.mp3"
  },
  {
    "speaker": "he",
    "text": "衣柜还是满的吗？",
    "src": "/audio/dialogue/he.0d1447f24850.f8b5c84c7560.mp3"
  },
  {
    "speaker": "he",
    "text": "周末去白沙吧，坐沿海慢车，当天就回来，也不用请假。",
    "src": "/audio/dialogue/he.19477e08875c.c93c4a9f0303.mp3"
  },
  {
    "speaker": "he",
    "text": "第一次领工资就想请你来。这次我请，你别抢着结账。",
    "src": "/audio/dialogue/he.19d425af271f.46d59bb324f2.mp3"
  },
  {
    "speaker": "he",
    "text": "我不是要你不看资料。只是想知道，这个周末我们能不能定下来。",
    "src": "/audio/dialogue/he.1d8d39ea00b1.012ff31f41c8.mp3"
  },
  {
    "speaker": "he",
    "text": "这张纸别碰水。先吃完，碗等会儿我们一起洗。",
    "src": "/audio/dialogue/he.232114ecb869.8e325ead75a8.mp3"
  },
  {
    "speaker": "he",
    "text": "先吃饭吧。明天的事，明天再一件件做。",
    "src": "/audio/dialogue/he.236866cd74c9.8426c2461129.mp3"
  },
  {
    "speaker": "he",
    "text": "两个车次都赶得上。你先吃面，等会儿我们再看看时间。",
    "src": "/audio/dialogue/he.27d1d05b7eab.d4bf1c554909.mp3"
  },
  {
    "speaker": "he",
    "text": "这几本先放里面吧。留出地方，师傅做事也方便些。",
    "src": "/audio/dialogue/he.2e6fc637c346.92fa37901813.mp3"
  },
  {
    "speaker": "he",
    "text": "去就一起订；这次不去，你也直接告诉我。",
    "src": "/audio/dialogue/he.348d314fe392.826344c3a2ca.mp3"
  },
  {
    "speaker": "he",
    "text": "你起来试试，腰能伸直吗？别又说垫一垫就好了。",
    "src": "/audio/dialogue/he.368e3a57dc72.ea13e20e6ac5.mp3"
  },
  {
    "speaker": "he",
    "text": "看那边，过完这段弯，海就能看得完整一点了。",
    "src": "/audio/dialogue/he.3998bba5ad9d.9de15f257e3b.mp3"
  },
  {
    "speaker": "he",
    "text": "不需要整理完所有东西。先留一格放衣服就好。",
    "src": "/audio/dialogue/he.456739310cc5.07f0fd8ce5d3.mp3"
  },
  {
    "speaker": "he",
    "text": "要是定下来，我就把那晚空出来。别到周五才告诉我。",
    "src": "/audio/dialogue/he.476ff85e71c3.190f03a19499.mp3"
  },
  {
    "speaker": "he",
    "text": "今晚还算数吗？我还没出门，怕你那边又有事情。",
    "src": "/audio/dialogue/he.4ebed456451f.90ee3a99b5df.mp3"
  },
  {
    "speaker": "he",
    "text": "菜市场那边新开了家面馆。一起去吗？",
    "src": "/audio/dialogue/he.5fcf01cbf52a.9c8821f3fe15.mp3"
  },
  {
    "speaker": "he",
    "text": "那我们就定在那天，不再说下次了。",
    "src": "/audio/dialogue/he.702840308497.e2b270478850.mp3"
  },
  {
    "speaker": "he",
    "text": "别熬太晚。到家记得把它挂起来。",
    "src": "/audio/dialogue/he.73d301ac19ee.defc06c3b6df.mp3"
  },
  {
    "speaker": "he",
    "text": "这两个车次都行，你挑一个吧，我把周末空出来。",
    "src": "/audio/dialogue/he.81f2f239b04e.4a7a5d4607ca.mp3"
  },
  {
    "speaker": "he",
    "text": "到站叫我一下。剩下的橘子给你，酸的那半我已经吃掉了。",
    "src": "/audio/dialogue/he.863522c54d47.305ded66bb61.mp3"
  },
  {
    "speaker": "he",
    "text": "刚想给你打电话。那就走吧，菜还热着。",
    "src": "/audio/dialogue/he.923fe3f805af.a3ca8c7e80be.mp3"
  },
  {
    "speaker": "he",
    "text": "又吃便利店的饭？我路过菜场，要不要一起买一点？",
    "src": "/audio/dialogue/he.a098b249ccdd.c62984a88526.mp3"
  },
  {
    "speaker": "he",
    "text": "先别忙着起身。你刚才一直皱着的眉头，松了点。",
    "src": "/audio/dialogue/he.a89972d9eb2e.5957ea90f2ec.mp3"
  },
  {
    "speaker": "he",
    "text": "那我周六带菜过来。",
    "src": "/audio/dialogue/he.a906c8bf0242.70caf2d69bc5.mp3"
  },
  {
    "speaker": "he",
    "text": "下次定好日子再叫我，我会把那晚空出来。",
    "src": "/audio/dialogue/he.aee5a97af228.ee8ebad56748.mp3"
  },
  {
    "speaker": "he",
    "text": "票转给同事了。电影还会再放，下回提前告诉我吧。",
    "src": "/audio/dialogue/he.b49b939334b1.65682a2bbb7c.mp3"
  },
  {
    "speaker": "he",
    "text": "要是每次有空再来，我们什么时候才算真的约好了？",
    "src": "/audio/dialogue/he.b6f01114a3c4.992110224cb9.mp3"
  },
  {
    "speaker": "he",
    "text": "饭还可以买。账也还能整理，你先选一件，别又两边都顾不上。",
    "src": "/audio/dialogue/he.b76193e2f144.a0806c24423a.mp3"
  },
  {
    "speaker": "he",
    "text": "过了这个弯，应该就能看见海。",
    "src": "/audio/dialogue/he.b781c52187d7.8d022919e6d2.mp3"
  },
  {
    "speaker": "he",
    "text": "我就是想，下次来时能在窗边坐坐，安安静静读一会儿。",
    "src": "/audio/dialogue/he.c67ed1c9199e.532780da323a.mp3"
  },
  {
    "speaker": "he",
    "text": "我想下次来能在窗边坐坐。但要做多少，我们得按自己的安排来。",
    "src": "/audio/dialogue/he.c8048531ad39.22e78327879e.mp3"
  },
  {
    "speaker": "he",
    "text": "你的葱我挑出来了。周末那趟沿海慢车，当天能来回。",
    "src": "/audio/dialogue/he.d358cb00a71f.4fa7e1f06f8a.mp3"
  },
  {
    "speaker": "he",
    "text": "刚才那一幕你看清了吗？我还在想，他为什么没有回头。",
    "src": "/audio/dialogue/he.d3e1600dbe2b.747443f3b8e8.mp3"
  },
  {
    "speaker": "he",
    "text": "那就下次吧。你这碗还没怎么吃，汤都快凉了。",
    "src": "/audio/dialogue/he.d7c6392955b9.e4f7896b3467.mp3"
  },
  {
    "speaker": "he",
    "text": "屋顶的确认单在这里。付款和盯施工的事，我们得分清楚。",
    "src": "/audio/dialogue/he.e159d34d5baa.a8d1967b2825.mp3"
  },
  {
    "speaker": "he",
    "text": "给你留着呢。纸先放远一点，别又把汤洒在账上。",
    "src": "/audio/dialogue/he.e80df3035d2b.1e084e3a2608.mp3"
  },
  {
    "speaker": "he",
    "text": "我把项目和付款人标出来了。哪一笔是你的，先看清楚再答复。",
    "src": "/audio/dialogue/he.f322572c10a1.b66985e28077.mp3"
  },
  {
    "speaker": "lu",
    "text": "能确认的写下来。不能保证的，就先不保证。",
    "src": "/audio/dialogue/lu.0c0fa5ec43d0.8973fd388962.mp3"
  },
  {
    "speaker": "lu",
    "text": "能公开的都在这里了。你慢慢读，漏的页再告诉我。",
    "src": "/audio/dialogue/lu.0ce67d324e5c.ddd8004929f6.mp3"
  },
  {
    "speaker": "lu",
    "text": "要不要借一笔一起买？机会就在这里，但报价没有保证。",
    "src": "/audio/dialogue/lu.0d1db0f58237.b2cf06105e8c.mp3"
  },
  {
    "speaker": "lu",
    "text": "先听完也行，别急。散场以后我们从后门走，人少点。",
    "src": "/audio/dialogue/lu.2f4651c79006.75aa188c3a69.mp3"
  },
  {
    "speaker": "lu",
    "text": "材料我都带来了。你要查，我们就把每页的日期找齐。",
    "src": "/audio/dialogue/lu.384fd1351b3d.b693b5211311.mp3"
  },
  {
    "speaker": "lu",
    "text": "我能带你进去，票和会费得自己付。想来就跟我说。",
    "src": "/audio/dialogue/lu.38d8ee7ced47.76a03d21e421.mp3"
  },
  {
    "speaker": "lu",
    "text": "回程不赶这班了。吃过饭再看。",
    "src": "/audio/dialogue/lu.5795e0e45cf9.d008cd33384c.mp3"
  },
  {
    "speaker": "lu",
    "text": "大家问订单什么时候变成钱。我每天去催，回来还是一样的答复。",
    "src": "/audio/dialogue/lu.63b064d8def0.4f155a1ccfd5.mp3"
  },
  {
    "speaker": "lu",
    "text": "到了那边，先找个地方吃午饭。",
    "src": "/audio/dialogue/lu.6ded6c1837ac.c9aef3c21f3e.mp3"
  },
  {
    "speaker": "lu",
    "text": "照片回来发你。下次我们提前约。",
    "src": "/audio/dialogue/lu.71d253b92d15.a071e486482f.mp3"
  },
  {
    "speaker": "lu",
    "text": "给你留了位置。周末来之前说一声，我去路口接你。",
    "src": "/audio/dialogue/lu.7b492d141263.b380549868c9.mp3"
  },
  {
    "speaker": "lu",
    "text": "扩建还在做，回款的计划又往后挪。最新一版我也夹进去了。",
    "src": "/audio/dialogue/lu.7cc92f151f54.04c4dd6976af.mp3"
  },
  {
    "speaker": "lu",
    "text": "我希望你来，不只是为了买股份。到了路口给我打电话。",
    "src": "/audio/dialogue/lu.7e3f56fb5849.e40288837d77.mp3"
  },
  {
    "speaker": "lu",
    "text": "后面的建设安排也留着。我转来那张图，没把小字截全。",
    "src": "/audio/dialogue/lu.7ea9c2a46605.01725d71415b.mp3"
  },
  {
    "speaker": "lu",
    "text": "老同学，这次总该轮到我们了。周末有空，过来看看？",
    "src": "/audio/dialogue/lu.81fe9cab12f9.8e56854188f0.mp3"
  },
  {
    "speaker": "lu",
    "text": "今天也不是非要你拿钱。就是想找个认识我的人，说说这一天。",
    "src": "/audio/dialogue/lu.84c913309124.ebe5ac074b0d.mp3"
  },
  {
    "speaker": "lu",
    "text": "新库已经起来了。周末来看看？好几个老同学也买了雾港冷链。",
    "src": "/audio/dialogue/lu.86520300e361.4c213bf5b97a.mp3"
  },
  {
    "speaker": "lu",
    "text": "大家都说，等价格回到最早那会儿就卖。最近总有人这样问。",
    "src": "/audio/dialogue/lu.87674ed57ab2.0c4b1d86fd8b.mp3"
  },
  {
    "speaker": "lu",
    "text": "其实今天找你，也没什么事。就是想坐一会儿。",
    "src": "/audio/dialogue/lu.8d782e2a7dea.e791d2db3a69.mp3"
  },
  {
    "speaker": "lu",
    "text": "街口卖早点的两口子也买了。你还记得他们那辆小推车吧？",
    "src": "/audio/dialogue/lu.8e6a9fef208f.c89ad9eb1fd2.mp3"
  },
  {
    "speaker": "lu",
    "text": "今天不赶回来，就能在对岸慢慢走一走。",
    "src": "/audio/dialogue/lu.a0d292ce292e.c935368be6a8.mp3"
  },
  {
    "speaker": "lu",
    "text": "总金额挺大，大家都在转这份公告。你也拿去看看。",
    "src": "/audio/dialogue/lu.a34c99ce244f.14e0d6342504.mp3"
  },
  {
    "speaker": "lu",
    "text": "大家问我订单什么时候变成钱。我每天都去催。",
    "src": "/audio/dialogue/lu.a72cba466cdc.d62e2f63f26d.mp3"
  },
  {
    "speaker": "lu",
    "text": "书店最近怎么样？大家都在问，做下来，究竟赚不赚钱？",
    "src": "/audio/dialogue/lu.adcf942d6998.a25907a6afb6.mp3"
  },
  {
    "speaker": "lu",
    "text": "这一栏是回款，别跟签单的日期抄到一起。我再给你找原表。",
    "src": "/audio/dialogue/lu.bbf30a0ebf7c.ff7244da9471.mp3"
  },
  {
    "speaker": "lu",
    "text": "他们都等着听你说，哪一次买得最漂亮。",
    "src": "/audio/dialogue/lu.c7427a94fe02.821b6d84f5c7.mp3"
  },
  {
    "speaker": "lu",
    "text": "后来他挑的是哪一本？你刚才说他站了很久，我还以为没进门。",
    "src": "/audio/dialogue/lu.caea0dec0887.d76aab41604e.mp3"
  },
  {
    "speaker": "lu",
    "text": "现有资料就这些。有的日期还没到，先别填成已经发生。",
    "src": "/audio/dialogue/lu.ccc9ee721a35.535f3c49840d.mp3"
  },
  {
    "speaker": "lu",
    "text": "大家都记着那个价。你觉得现在该看什么？",
    "src": "/audio/dialogue/lu.cf69d613ff64.0e030ff92148.mp3"
  },
  {
    "speaker": "lu",
    "text": "好，各人按各人的安排来。对了，那家面馆又换招牌了。",
    "src": "/audio/dialogue/lu.d2dbfe2d2002.e47a800c48c7.mp3"
  },
  {
    "speaker": "lu",
    "text": "回来，还是一样的回答。",
    "src": "/audio/dialogue/lu.d9efbda9b847.7cdf9fe68ba6.mp3"
  },
  {
    "speaker": "lu",
    "text": "好久不说话的同学也来问了：你是不是还在等？",
    "src": "/audio/dialogue/lu.e278e1143bc1.f440040bd5e0.mp3"
  },
  {
    "speaker": "lu",
    "text": "第一批货还没到，电费已经走了。照片里看不出这么空。",
    "src": "/audio/dialogue/lu.feacdf2d567b.c70172a9bfa5.mp3"
  },
  {
    "speaker": "lu",
    "text": "项目还在做。可账上的订单多，不等于这个月就能收到钱。",
    "src": "/audio/dialogue/lu.ffc18798c922.da9b7006d9c9.mp3"
  },
  {
    "speaker": "ning",
    "text": "修改和这次交付分开写，谁也别把它当作已经完成。",
    "src": "/audio/dialogue/ning.398660fd02c3.d72f667e15fc.mp3"
  },
  {
    "speaker": "ning",
    "text": "照片我存好了。这张我带走，留给你的那联别弄丢。",
    "src": "/audio/dialogue/ning.3ff43f95846e.07f76c2eb92a.mp3"
  },
  {
    "speaker": "ning",
    "text": "重做这一页，今晚要返工。按签过的版本交，也得让客户知道错处还在。",
    "src": "/audio/dialogue/ning.46264ca8e170.05196e73934f.mp3"
  },
  {
    "speaker": "ning",
    "text": "器材已经通过验收，客户满意。付款还要照流程往下走。",
    "src": "/audio/dialogue/ning.4c1efef46fb0.d318333a152e.mp3"
  },
  {
    "speaker": "ning",
    "text": "原来运费也变了。下次我把家里那几本旧书带来。",
    "src": "/audio/dialogue/ning.57ab72ab1d92.2cdbc8ef056c.mp3"
  },
  {
    "speaker": "ning",
    "text": "下本书的排期，等你们吃过饭再谈。",
    "src": "/audio/dialogue/ning.59bf5942aabb.1b109f9ec4e6.mp3"
  },
  {
    "speaker": "ning",
    "text": "这份是唯一的原件吧？销毁就行，我会另付一笔费用。",
    "src": "/audio/dialogue/ning.7cceabc261c8.6d28cb580ab4.mp3"
  },
  {
    "speaker": "ning",
    "text": "那就按实际数。这份重开，我把前面那张一起收起来。",
    "src": "/audio/dialogue/ning.9197a812106f.9e554f206bbb.mp3"
  },
  {
    "speaker": "ning",
    "text": "我把电话留在这里。你们决定好了，我们一起说明。",
    "src": "/audio/dialogue/ning.940e6f0b4bca.bb4f123540bb.mp3"
  },
  {
    "speaker": "ning",
    "text": "记录留下，我逐项核一遍。延期也给你们写清楚。",
    "src": "/audio/dialogue/ning.99d5edc3d13d.0145c38ec0f7.mp3"
  },
  {
    "speaker": "ning",
    "text": "流程表也一起留下吧。已签完的和还没签的，别弄混了。",
    "src": "/audio/dialogue/ning.a450fec57efc.c5665e36f890.mp3"
  },
  {
    "speaker": "ning",
    "text": "下回还照这个吗？那我得先问好，免得又记错。",
    "src": "/audio/dialogue/ning.ae9d696fa52e.39f40aeb16d6.mp3"
  },
  {
    "speaker": "ning",
    "text": "这几页也一起看了吧，下次补给你。我先把文件传过来。",
    "src": "/audio/dialogue/ning.bcdc7f10f8f4.a30f5a218f37.mp3"
  },
  {
    "speaker": "ning",
    "text": "费用已经转过去了。那张原件，你这边已经处理掉了吧？",
    "src": "/audio/dialogue/ning.bf7507740cab.90ec4eb12791.mp3"
  },
  {
    "speaker": "ning",
    "text": "按这个数开，我多付你一笔。实际的支出，你已经知道了。",
    "src": "/audio/dialogue/ning.cc856ed2cfec.6aa02f14ce0a.mp3"
  },
  {
    "speaker": "ning",
    "text": "这一页我也喜欢。我再看一眼，纸就不用重新包了。",
    "src": "/audio/dialogue/ning.d1221cbce73e.907742a0d96e.mp3"
  },
  {
    "speaker": "ning",
    "text": "头一单便宜些，往后可以长期合作，咱们先互相试试。",
    "src": "/audio/dialogue/ning.d3c53abddbe9.ab9a7cf80155.mp3"
  },
  {
    "speaker": "ning",
    "text": "可以重新确认贡献，结算也得顺延。你们想清楚。",
    "src": "/audio/dialogue/ning.d5f90c007918.f5a78b723555.mp3"
  },
  {
    "speaker": "ning",
    "text": "还是这一本，怎么贵了这么多？以前我就在这里买过。",
    "src": "/audio/dialogue/ning.e6ab7199ba8b.d6cc9dc68e88.mp3"
  },
  {
    "speaker": "ning",
    "text": "这个价可以吗？找了很久，今天总算在这里看到一本。",
    "src": "/audio/dialogue/ning.ed1eec411190.c2cd659e9f31.mp3"
  },
  {
    "speaker": "tang",
    "text": "靠窗的位置留着呢。水刚烧好。",
    "src": "/audio/dialogue/tang.01bc9014d95f.7d892818c4bc.mp3"
  },
  {
    "speaker": "tang",
    "text": "来读书的人多了，收拾的人没多。我们得把开门和关门一起安排。",
    "src": "/audio/dialogue/tang.01cc447db63f.d60743d56a05.mp3"
  },
  {
    "speaker": "tang",
    "text": "收旧设备的人下午来过。他问，我什么时候能给个准话。",
    "src": "/audio/dialogue/tang.02693853c602.ee8a84563e11.mp3"
  },
  {
    "speaker": "tang",
    "text": "这次不办也能说。只是桌子和人的时间，都得提前安排。",
    "src": "/audio/dialogue/tang.048c1aeeea8b.a3b3435b3942.mp3"
  },
  {
    "speaker": "tang",
    "text": "借的是这笔，我单独记。订金那边，也得再去确认日期。",
    "src": "/audio/dialogue/tang.0bb203a2d948.caa0a177fdf3.mp3"
  },
  {
    "speaker": "tang",
    "text": "毕业册的单子接到了。修机器要两万，回款得等到明年。",
    "src": "/audio/dialogue/tang.203b03d5adf1.416b4711e583.mp3"
  },
  {
    "speaker": "tang",
    "text": "这次要是筹不到，我就去别家印坊找工作。收旧设备的人也来问过。",
    "src": "/audio/dialogue/tang.22af51df8a81.84a41b8300d9.mp3"
  },
  {
    "speaker": "tang",
    "text": "留下，先把现有的地方维护好。不留下，我们就一项项交清楚。",
    "src": "/audio/dialogue/tang.23ff4c8c4936.aa559471a0bb.mp3"
  },
  {
    "speaker": "tang",
    "text": "一下又开了三家，可老店门口的队，还是原来那么长。",
    "src": "/audio/dialogue/tang.257944999b48.2822624d17c5.mp3"
  },
  {
    "speaker": "tang",
    "text": "这张你收着。订单里的确认栏，我明天还得去催。",
    "src": "/audio/dialogue/tang.2e2deefce2b1.1b2aaa7d2ddc.mp3"
  },
  {
    "speaker": "tang",
    "text": "借给街坊晒书，还是留给店里周转？得先空出半天。",
    "src": "/audio/dialogue/tang.2f1bf9724288.4f2c62b669d5.mp3"
  },
  {
    "speaker": "tang",
    "text": "印坊接了毕业册。机器修好才能交货，维修要两万元。",
    "src": "/audio/dialogue/tang.34f0b79296aa.a9a2608efa94.mp3"
  },
  {
    "speaker": "tang",
    "text": "这次我也只认一班。其他的，咱们一起排。",
    "src": "/audio/dialogue/tang.369af92b31be.803d3e7d71d0.mp3"
  },
  {
    "speaker": "tang",
    "text": "这张桌子留到最后搬吧。别的东西，我先一项项记下来。",
    "src": "/audio/dialogue/tang.3946ceeec7a9.6b7f62af1e71.mp3"
  },
  {
    "speaker": "tang",
    "text": "我联系能处理的回收站，先别堵着门，让人有路进来。",
    "src": "/audio/dialogue/tang.39d8ed617cf7.ab5d691ff621.mp3"
  },
  {
    "speaker": "tang",
    "text": "好了，不晃。划痕就留着吧，书摊开也盖不住几道。",
    "src": "/audio/dialogue/tang.3d6bcc5e83b4.f7e0a6eb3e46.mp3"
  },
  {
    "speaker": "tang",
    "text": "周末那两班，我还能再顶一阵。",
    "src": "/audio/dialogue/tang.406373b3a204.7b7700129ff6.mp3"
  },
  {
    "speaker": "tang",
    "text": "你定一条，我就把表补齐。以后有变动，再提前一起改。",
    "src": "/audio/dialogue/tang.42cb3c6ea238.ab3f0eb3c65d.mp3"
  },
  {
    "speaker": "tang",
    "text": "那今天先盘点这两架，受潮的放高一点。",
    "src": "/audio/dialogue/tang.44b1c5167e30.d6954d133c0b.mp3"
  },
  {
    "speaker": "tang",
    "text": "这几本得晚几天来取。我先通知等书的人，别让他们白跑。",
    "src": "/audio/dialogue/tang.47b7ea1a7f63.51885a5f26ba.mp3"
  },
  {
    "speaker": "tang",
    "text": "旧划痕多了点，倒是真结实。周五放书、放杯子都够。",
    "src": "/audio/dialogue/tang.4df93bb76134.a533d38899d2.mp3"
  },
  {
    "speaker": "tang",
    "text": "送是白送。得一箱箱筛，发霉的也不能就这样摆上架。",
    "src": "/audio/dialogue/tang.5626c30b4c21.bea2237cdc2d.mp3"
  },
  {
    "speaker": "tang",
    "text": "你慢慢想。我先把门口扫了，风一大，纸屑又都跑回来了。",
    "src": "/audio/dialogue/tang.5958eb1d0f89.0fd25b44927c.mp3"
  },
  {
    "speaker": "tang",
    "text": "等一下，这一天我得再算一遍。不能为了快，就先写下去。",
    "src": "/audio/dialogue/tang.5d0d34cdbf41.c8e5a982af9a.mp3"
  },
  {
    "speaker": "tang",
    "text": "这层低一点，拿书方便。柜台边上，也给人留条好走的路。",
    "src": "/audio/dialogue/tang.5f327a495f14.1538bd8f5a16.mp3"
  },
  {
    "speaker": "tang",
    "text": "末班车还有一会儿。你刚才说的那一段，能再读一次吗？",
    "src": "/audio/dialogue/tang.6ba711f75e38.e9778d550737.mp3"
  },
  {
    "speaker": "tang",
    "text": "可以只坐一会儿。那边有水，书看完放在桌上就好。",
    "src": "/audio/dialogue/tang.6f02ee82cd80.0c24d75c34e3.mp3"
  },
  {
    "speaker": "tang",
    "text": "接下来还做不做，要早点说。进书、维护和交接，都得留时间。",
    "src": "/audio/dialogue/tang.6fe0380fe0e1.222ab76df587.mp3"
  },
  {
    "speaker": "tang",
    "text": "他们下课晚，想进来时总关门。能不能多开一个小时？",
    "src": "/audio/dialogue/tang.76dec79ef898.7bcba73a1225.mp3"
  },
  {
    "speaker": "tang",
    "text": "这边先这么摆，拿书的人不用再绕过一整张桌子。",
    "src": "/audio/dialogue/tang.852115ac06c9.c5789da80594.mp3"
  },
  {
    "speaker": "tang",
    "text": "白天有人来找书，晚上却只能站在门口。周五留张桌子给大家，好不好？",
    "src": "/audio/dialogue/tang.86e7035e6b8c.d47f83cb4b31.mp3"
  },
  {
    "speaker": "tang",
    "text": "你喝口水。我把桌面收一收，这些单子不能再混着放了。",
    "src": "/audio/dialogue/tang.88b424843120.613f5ff22105.mp3"
  },
  {
    "speaker": "tang",
    "text": "这本留着吧。先晾一晾，再把这些小字慢慢看看。",
    "src": "/audio/dialogue/tang.8a970bf5872c.939779b6f60b.mp3"
  },
  {
    "speaker": "tang",
    "text": "这只还热着，小心点。我去关里面的灯，门口那盏留给你。",
    "src": "/audio/dialogue/tang.8b033acedb7c.35f48e17cb23.mp3"
  },
  {
    "speaker": "tang",
    "text": "修好就能开工。还差一万二，你看，交货日期也改过了。",
    "src": "/audio/dialogue/tang.8d21d7e5591a.da30e141c924.mp3"
  },
  {
    "speaker": "tang",
    "text": "借出去以后，几点关门、谁来收杯子，都得先说好。",
    "src": "/audio/dialogue/tang.92bf1cdbda0f.202babc1b449.mp3"
  },
  {
    "speaker": "tang",
    "text": "原来这个点外面这么亮。那我也先走了，回来再见。",
    "src": "/audio/dialogue/tang.9a1561bb1e60.bd0b0e13b5e1.mp3"
  },
  {
    "speaker": "tang",
    "text": "你想好再写。我先把门口扫干净。",
    "src": "/audio/dialogue/tang.a126638769de.fa399961fc6d.mp3"
  },
  {
    "speaker": "tang",
    "text": "我的名字排了五晚。剩下两格，不能总等到当天再问人。",
    "src": "/audio/dialogue/tang.a6ca259df2e1.db003b1f608f.mp3"
  },
  {
    "speaker": "tang",
    "text": "别再把一个人的名字填满一整列。你选好办法，咱们就照着写。",
    "src": "/audio/dialogue/tang.a777de39c52d.3a768f1ee5e5.mp3"
  },
  {
    "speaker": "tang",
    "text": "先留着这张吧。以后想调整，再对着他们下课的点商量。",
    "src": "/audio/dialogue/tang.a88b660cc0f3.6cadcb818b4d.mp3"
  },
  {
    "speaker": "tang",
    "text": "明年的营业时间，还要不要改？这块砖先弄好，免得绊着人。",
    "src": "/audio/dialogue/tang.a96abb42907d.704494b09000.mp3"
  },
  {
    "speaker": "tang",
    "text": "分开才看得出来。刚才那张总表，我还以为每家都变好了。",
    "src": "/audio/dialogue/tang.a9934b96159e.63bfda1aa657.mp3"
  },
  {
    "speaker": "tang",
    "text": "客户改了交货日。现在修好机器，还差一万二。",
    "src": "/audio/dialogue/tang.aa77676f1742.9104adf9dcee.mp3"
  },
  {
    "speaker": "tang",
    "text": "这两份得补签。今晚辛苦你了，我带着它们再跑一趟。",
    "src": "/audio/dialogue/tang.b1acc0ba819d.d25efb57a4d3.mp3"
  },
  {
    "speaker": "tang",
    "text": "星期五，腾一张桌子吧。让街坊带自己喜欢的东西来读。",
    "src": "/audio/dialogue/tang.b74d3421208d.3a4b9bf70652.mp3"
  },
  {
    "speaker": "tang",
    "text": "我想向你借这笔钱。约定回款在一年后，借据和日期都写清楚。",
    "src": "/audio/dialogue/tang.b78e6bd597a1.742dea23a9d9.mp3"
  },
  {
    "speaker": "tang",
    "text": "司机报过价了，让老板自己确认，我们别代签。",
    "src": "/audio/dialogue/tang.b821bff2468e.b4d491d08c75.mp3"
  },
  {
    "speaker": "tang",
    "text": "门先别关，还有个人在路上。",
    "src": "/audio/dialogue/tang.be10718443ad.a2358c5cc59b.mp3"
  },
  {
    "speaker": "tang",
    "text": "先别急着放回去。最里头这两本，再摊一会儿。",
    "src": "/audio/dialogue/tang.be9f4e9f6ac8.b829fde5b3ae.mp3"
  },
  {
    "speaker": "tang",
    "text": "不收门票。椅子得添几把，散场以后，也得有人收拾。",
    "src": "/audio/dialogue/tang.c34359e6018c.8979b19df587.mp3"
  },
  {
    "speaker": "tang",
    "text": "你不借，也能帮我看看缺哪些文件。我明天去找客户补。",
    "src": "/audio/dialogue/tang.c5cc7d269f2d.1ffefdc2e195.mp3"
  },
  {
    "speaker": "tang",
    "text": "下面收好了。你这份做完，记得也起来走一走。",
    "src": "/audio/dialogue/tang.ca4f05913c59.a7c1e5eea195.mp3"
  },
  {
    "speaker": "tang",
    "text": "这半天留给各自的生活，或者周五多开一晚。笔在这里。",
    "src": "/audio/dialogue/tang.ce1b49644bc9.5599462b8753.mp3"
  },
  {
    "speaker": "tang",
    "text": "订金到得慢，学校不会跑。我把维修的报价也带过来了。",
    "src": "/audio/dialogue/tang.d3700edb9912.bb680395abf3.mp3"
  },
  {
    "speaker": "tang",
    "text": "下周那班要不要换一下？先走吧，门我们会关。",
    "src": "/audio/dialogue/tang.dcf3dc04e935.893e80d63437.mp3"
  },
  {
    "speaker": "tang",
    "text": "周五常有人来读它。书要是卖了，桌上这一格就空了。",
    "src": "/audio/dialogue/tang.de2995770297.9165d38395e5.mp3"
  },
  {
    "speaker": "tang",
    "text": "不收门票。得添椅子，也得有人留下来开门、收拾。",
    "src": "/audio/dialogue/tang.e1d79158ed5a.11bc9150df34.mp3"
  },
  {
    "speaker": "tang",
    "text": "下次下雨再来看。这个位置先别摆书，木梁的事也记着。",
    "src": "/audio/dialogue/tang.e1fdde7b067d.0c1c2ea1047e.mp3"
  },
  {
    "speaker": "tang",
    "text": "桌子朝哪边放？靠窗会冷些，不过那边的光倒是很好。",
    "src": "/audio/dialogue/tang.e992d12ac468.df6c67e3a867.mp3"
  },
  {
    "speaker": "tang",
    "text": "轮流看一会儿，或者问辆冷藏车。得有人先把价格问清。",
    "src": "/audio/dialogue/tang.f3905355a33b.8a80f5e494ce.mp3"
  },
  {
    "speaker": "tang",
    "text": "你把今天能答应的说清楚就行。旧账和这笔新的，别混着写。",
    "src": "/audio/dialogue/tang.f4d403ec9138.fbd658762616.mp3"
  },
  {
    "speaker": "tang",
    "text": "那先不搬。我把桌上的东西收好，下次量起来也快。",
    "src": "/audio/dialogue/tang.f4e80ea33c8c.f0c91e135cbc.mp3"
  },
  {
    "speaker": "tang",
    "text": "就停在这里吧，下个人来读，还能接上上一回那几行。",
    "src": "/audio/dialogue/tang.fc0cd6eb8ab4.2b16193bd4fa.mp3"
  },
  {
    "speaker": "tang",
    "text": "供货商把日子提前了，熟客订金要下季才到，差这一段。",
    "src": "/audio/dialogue/tang.fca370892a38.402fc4168b87.mp3"
  },
  {
    "speaker": "xu",
    "text": "原件我看过了。添两笔收入，日期再挪一下，这份就顺了。",
    "src": "/audio/dialogue/xu.054a895c3a52.dcbaf88eb1da.mp3"
  },
  {
    "speaker": "xu",
    "text": "大家只是补手续。你肯签，我这边给一笔介绍费。",
    "src": "/audio/dialogue/xu.2924c3e2f615.2c072af26560.mp3"
  },
  {
    "speaker": "xu",
    "text": "这样好看许多。钱反正进过账，你签一下，协作费另给。",
    "src": "/audio/dialogue/xu.34340a4e770d.da23a3ff108f.mp3"
  },
  {
    "speaker": "xu",
    "text": "清单我收着。那我去联系负责验收的人，再把缺项问清楚。",
    "src": "/audio/dialogue/xu.4dec3bb3ebd3.0efe8f8fff5a.mp3"
  },
  {
    "speaker": "xu",
    "text": "盖个章，费用就按说好的来。证明的内容我已经替你填好了。",
    "src": "/audio/dialogue/xu.5bec8c0790ab.b59e59ad3c7a.mp3"
  },
  {
    "speaker": "xu",
    "text": "日期也能调整。你先看看签字的地方，原件不用摆在这儿。",
    "src": "/audio/dialogue/xu.5d5a99f849fa.bfbf913fa966.mp3"
  },
  {
    "speaker": "xu",
    "text": "这一页我收了。原件你自己放好，别和这份混在一起。",
    "src": "/audio/dialogue/xu.6e7751c3be88.cf05e3e483f7.mp3"
  },
  {
    "speaker": "xu",
    "text": "前面这几次你都看到了，下一轮名单要付费，今晚可以加入。",
    "src": "/audio/dialogue/xu.972971713e74.a3e112bf82f9.mp3"
  },
  {
    "speaker": "xu",
    "text": "复印件也带上。后面有人问材料，就能照着这个联系你。",
    "src": "/audio/dialogue/xu.c245f86538d6.fdf5f88df8fb.mp3"
  },
  {
    "speaker": "xu",
    "text": "流水好看些，续贷和转租都好办。大家只是把手续补齐而已。",
    "src": "/audio/dialogue/xu.ca36783f89f9.8a2fea390c98.mp3"
  },
  {
    "speaker": "xu",
    "text": "这页我带走。还款的合同你留着，那是另外一份。",
    "src": "/audio/dialogue/xu.ca983f575eab.311bd4cad037.mp3"
  },
  {
    "speaker": "xu",
    "text": "人今天不在，你替他写一下。原件不会有人专门来查的。",
    "src": "/audio/dialogue/xu.da35b0bd1a4f.ae145a23a1cc.mp3"
  },
  {
    "speaker": "xu",
    "text": "我把这一份带走。笔给我吧，后面的材料我来装。",
    "src": "/audio/dialogue/xu.fd3f68a57d58.2cf9b81abc39.mp3"
  },
  {
    "speaker": "yao",
    "text": "领取确认也分别签，不替别人保证。",
    "src": "/audio/dialogue/yao.0126530030d6.0307d1715200.mp3"
  },
  {
    "speaker": "yao",
    "text": "这两个日期我再核一次。您稍等，资料先不要收起来。",
    "src": "/audio/dialogue/yao.11419d9aaf65.3d3089b9d639.mp3"
  },
  {
    "speaker": "yao",
    "text": "可以现在结清，也能拆到下一季。您看，合计在这两行。",
    "src": "/audio/dialogue/yao.22d02e48cf67.af5e412f3434.mp3"
  },
  {
    "speaker": "yao",
    "text": "原件保留。新条件附后面，每个人核对自己的那一行。",
    "src": "/audio/dialogue/yao.75e5fb31a03b.c14a471949be.mp3"
  },
  {
    "speaker": "yao",
    "text": "付款总额也请抄完整。到那一天，要付的是下面这一行。",
    "src": "/audio/dialogue/yao.8ec9ff65d1fa.c153fb1de60b.mp3"
  },
  {
    "speaker": "yao",
    "text": "借款和还款，都先核对日期。",
    "src": "/audio/dialogue/yao.9d561868b4e1.10274caac55e.mp3"
  },
  {
    "speaker": "yao",
    "text": "经济安排可以改。改了什么，要另写清楚。",
    "src": "/audio/dialogue/yao.d11322db5757.824f4ad11603.mp3"
  },
  {
    "speaker": "yao",
    "text": "这联您收好。回去对账时，照上面的实际金额核就行。",
    "src": "/audio/dialogue/yao.edf490445b82.a3d82810c902.mp3"
  },
  {
    "speaker": "zhou",
    "text": "这张留好。东西清点一遍，回去要用的可别落下。",
    "src": "/audio/dialogue/zhou.08f8af4e0a89.eea9fa654557.mp3"
  },
  {
    "speaker": "zhou",
    "text": "那就把这一笔单写清楚。你看，我这里还有没有漏的？",
    "src": "/audio/dialogue/zhou.202db46e57cd.b22645c95685.mp3"
  },
  {
    "speaker": "zhou",
    "text": "土地是有不少，可银行这回条件紧，还在谈续期呢。",
    "src": "/audio/dialogue/zhou.29ee92216269.15c1faddb19a.mp3"
  },
  {
    "speaker": "zhou",
    "text": "我带了茶叶。下次轮到谁，咱们慢慢排。",
    "src": "/audio/dialogue/zhou.48e5c14c364b.d2876db9290e.mp3"
  },
  {
    "speaker": "zhou",
    "text": "菜得先搬进箱子。等多久，现在谁也说不好。",
    "src": "/audio/dialogue/zhou.4c9730ea16bb.6d26b07c22f8.mp3"
  },
  {
    "speaker": "zhou",
    "text": "多预付一季能便宜两百。要是搬走，这笔就不退了。",
    "src": "/audio/dialogue/zhou.7cba838f1d88.e1316db167c7.mp3"
  },
  {
    "speaker": "zhou",
    "text": "替亲戚周转一下，借个签名，不会真麻烦到你的。",
    "src": "/audio/dialogue/zhou.7e0c57aa70ce.ceb81b63e067.mp3"
  },
  {
    "speaker": "zhou",
    "text": "现结便宜两百；下季按原价付也行，你自己挑。",
    "src": "/audio/dialogue/zhou.9c1fbca6b4e1.cf2da5623714.mp3"
  },
  {
    "speaker": "zhou",
    "text": "现在拿就少一点；要全额，还得再等一季，你来定。",
    "src": "/audio/dialogue/zhou.a25dfb672789.aae3678114f8.mp3"
  },
  {
    "speaker": "zhou",
    "text": "钥匙在呢。你放心去吃饭。",
    "src": "/audio/dialogue/zhou.a85a606e02c3.e0b4feb204cc.mp3"
  },
  {
    "speaker": "zhou",
    "text": "我记着。先问清楚也好，亲戚那头我再去说一说。",
    "src": "/audio/dialogue/zhou.bab06a97f5ef.5d978c02307b.mp3"
  },
  {
    "speaker": "zhou",
    "text": "到时带这张来，咱们照着它核，省得各记各的。",
    "src": "/audio/dialogue/zhou.cb3dead71146.f9485e62acab.mp3"
  },
  {
    "speaker": "zhou",
    "text": "你先回去。那张清单留给我，咱们照着接。",
    "src": "/audio/dialogue/zhou.d13069cf273c.b3985d902a0b.mp3"
  },
  {
    "speaker": "zhou",
    "text": "这天像还得下。你先走吧，我去把外面的东西搬进来。",
    "src": "/audio/dialogue/zhou.d39e6f40bc2e.4efcf2624f8d.mp3"
  },
  {
    "speaker": "zhou",
    "text": "你再过一遍，别急。数对了，这一次咱们就结在今天。",
    "src": "/audio/dialogue/zhou.e49a747b09b8.30fc3f64e030.mp3"
  },
  {
    "speaker": "zhou",
    "text": "下季抵扣就按这张来。你留原件，我这边也记一份。",
    "src": "/audio/dialogue/zhou.eccbbdc07ffa.4227b2bd1680.mp3"
  },
  {
    "speaker": "zhou",
    "text": "他们说跌到这个价，已经不会再跌。你看，大家都这么想。",
    "src": "/audio/dialogue/zhou.ed8aa7f7cc1e.5b60a2b95038.mp3"
  },
  {
    "speaker": "zhou",
    "text": "那就等银行的答复。我也再看看，别把估价当现钱用了。",
    "src": "/audio/dialogue/zhou.fa44dcaa1e05.c23ae0513b2c.mp3"
  }
] as const satisfies readonly SpokenClip[];
